// shared/schemas/eventLog.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";
import { EndUserReferenceSchema } from "./endUser.schema";

/**
 * Base EventLog Schema — core database structure.
 */
export const EventLogBaseSchema = z.object({
  id: z.uuid(),
  appId: z.uuid(),
  endUserId: z.uuid().optional(),
  type: z.string(),
  payload: z.any(),
  createdAt: z.date(),
});

/**
 * Reference version — for lightweight embedding in other entities.
 */
export const EventLogReferenceSchema = EventLogBaseSchema.pick({
  id: true,
  appId: true,
  endUserId: true,
  type: true,
  createdAt: true,
});

/**
 * Detailed version — includes relational references.
 */
export const EventLogDetailedSchema = EventLogBaseSchema.extend({
  app: z.lazy(() => AppReferenceSchema),
  endUser: z.lazy(() => EndUserReferenceSchema).optional(),
});

export type EventLogBase = z.infer<typeof EventLogBaseSchema>;
export type EventLogReference = z.infer<typeof EventLogReferenceSchema>;
export type EventLogDetailed = z.infer<typeof EventLogDetailedSchema>;
