// shared/schemas/allowedOrigin.schema.ts
import { z } from "zod";
import { OrganizationReferenceSchema } from "./organization.schema";

/**
 * Base schema — core fields for AllowedOrigin
 */
export const AllowedOriginBaseSchema = z.object({
  id: z.uuid(),
  organizationId: z.uuid(),
  origin: z.string(),
  createdAt: z.date(),
});

/**
 * Reference schema — minimal for embedding in other models
 */
export const AllowedOriginReferenceSchema = AllowedOriginBaseSchema.pick({
  id: true,
  organizationId: true,
  origin: true,
  createdAt: true,
});

/**
 * Detailed schema — includes nested organization
 */
export const AllowedOriginDetailedSchema = AllowedOriginBaseSchema.extend({
  organization: z
    .lazy(() => OrganizationReferenceSchema)
    .optional()
    .nullable(),
});

// ─────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────
export type AllowedOriginBase = z.infer<typeof AllowedOriginBaseSchema>;
export type AllowedOriginReference = z.infer<
  typeof AllowedOriginReferenceSchema
>;
export type AllowedOriginDetailed = z.infer<typeof AllowedOriginDetailedSchema>;

/**
 * Input schemas
 */
export const AddAllowedOriginInputSchema = z.object({
  organizationId: z.uuid(),
  origin: z.string().min(1),
});
export type AddAllowedOriginInput = z.infer<typeof AddAllowedOriginInputSchema>;

export const RemoveAllowedOriginInputSchema = z.object({
  organizationId: z.uuid(),
  origin: z.string().min(1),
});
export type RemoveAllowedOriginInput = z.infer<
  typeof RemoveAllowedOriginInputSchema
>;
