// shared/schemas/changeLog.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";

/**
 * Base ChangeLog Schema — represents the core DB record.
 */
export const ChangeLogBaseSchema = z.object({
  id: z.uuid(),
  tableName: z.string().min(1, "Table name is required."),
  recordId: z.string().min(1, "Record ID is required."),
  appId: z.uuid().optional(),
  action: z.string().min(1, "Action is required."),
  changedBy: z.uuid().optional(),
  before: z.any().optional(),
  after: z.any().optional(),
  createdAt: z.date(),
});

/**
 * Reference version — minimal fields for relational linking.
 * Used when embedding ChangeLog summaries in other entities.
 */
export const ChangeLogReferenceSchema = ChangeLogBaseSchema.pick({
  id: true,
  tableName: true,
  recordId: true,
  action: true,
  createdAt: true,
});

/**
 * Detailed version — includes expanded relations and full change diff.
 * Used for API responses or admin log inspection views.
 */
export const ChangeLogDetailedSchema = ChangeLogBaseSchema.extend({
  app: AppReferenceSchema.optional(),
});

export type ChangeLogBase = z.infer<typeof ChangeLogBaseSchema>;
export type ChangeLogReference = z.infer<typeof ChangeLogReferenceSchema>;
export type ChangeLogDetailed = z.infer<typeof ChangeLogDetailedSchema>;
