// shared/schemas/appMetric.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";

/**
 * Base schema for AppMetric
 * Contains the core fields for creation / updates
 */
export const AppMetricBaseSchema = z.object({
  appId: z.string(),
  metric: z.string(), // e.g., "tokens", "vCPU-hours", "VRAM-MB"
  value: z.number(),
  recordedAt: z.date().optional(), // optional if you want to default to now
});

export type AppMetricBase = z.infer<typeof AppMetricBaseSchema>;

/**
 * Minimal / Reference schema for AppMetric
 * Includes unique identifiers
 */
export const AppMetricReferenceSchema = AppMetricBaseSchema.extend({
  id: z.uuid(),
  recordedAt: z.date(), // ensure timestamp exists in reference schema
});

export type AppMetricReference = z.infer<typeof AppMetricReferenceSchema>;

/**
 * Full / Detailed schema for AppMetric
 * Includes nested app reference
 */
export const AppMetricDetailedSchema = AppMetricReferenceSchema.extend({
  app: z.lazy(() => AppReferenceSchema),
});

export type AppMetricDetailed = z.infer<typeof AppMetricDetailedSchema>;
