// apps/shared/lib/jwtDecode.ts
import { jwtDecode } from "jwt-decode";
import { type JwtPayload, JwtPayloadSchema } from "./jwt";

/**
 * Lightweight JWT decoder for Edge/Browser-safe environments.
 * ❗ Does NOT verify the signature — use only for client-side checks
 * or route guarding, not for secure authentication.
 *
 * @param token - JWT string to decode
 * @returns Parsed JWT payload if valid, otherwise `null`
 *
 * @example
 * const payload = decodeJwt(token);
 * if (payload?.userId) {
 *   // Allow route access
 * }
 */
export function decodeJwt(token: string): JwtPayload | null {
  try {
    // Decode the JWT payload without verifying the signature
    const decoded = jwtDecode<Partial<JwtPayload>>(token);

    // If there are numeric timestamps as strings, safely parse them
    const normalized = {
      ...decoded,
      iat:
        typeof decoded.iat === "string"
          ? Number.parseInt(decoded.iat, 10)
          : decoded.iat,
      exp:
        typeof decoded.exp === "string"
          ? Number.parseInt(decoded.exp, 10)
          : decoded.exp,
    };

    // Validate payload against Zod schema
    return JwtPayloadSchema.parse(normalized);
  } catch {
    return null;
  }
}
