// shared/schemas/sdkLog.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";
import { EndUserReferenceSchema } from "./endUser.schema";

/**
 * Base schema — core SDK log fields
 */
export const SdkLogBaseSchema = z.object({
  id: z.uuid(),
  appId: z.string(),
  endUserId: z.string().optional(),
  method: z.string(),
  payload: z.any(),
  createdAt: z.date(),
});

/**
 * Reference schema — minimal info for embedding elsewhere
 */
export const SdkLogReferenceSchema = SdkLogBaseSchema.pick({
  id: true,
  method: true,
  createdAt: true,
});

/**
 * Detailed schema — includes nested relations
 */
export const SdkLogDetailedSchema = SdkLogBaseSchema.extend({
  app: z.lazy(() => AppReferenceSchema),
  endUser: z.lazy(() => EndUserReferenceSchema).optional(),
});

// Types
export type SdkLogBase = z.infer<typeof SdkLogBaseSchema>;
export type SdkLogReference = z.infer<typeof SdkLogReferenceSchema>;
export type SdkLogDetailed = z.infer<typeof SdkLogDetailedSchema>;
