// shared/schemas/usageLimit.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";
import { EndUserReferenceSchema } from "./endUser.schema";

/**
 * Base schema — core usage limit fields
 */
export const UsageLimitBaseSchema = z.object({
  id: z.uuid(),
  appId: z.string(),
  endUserId: z.string().optional(),
  metric: z.string(),
  limit: z.number(),
  period: z.enum(["daily", "weekly", "monthly", "yearly", "lifetime"]),
  metadata: z.record(z.string(), z.any()).optional(),
  resetAt: z.date().optional(),
  createdAt: z.date(),
  updatedAt: z.date().optional(),
});

/**
 * Reference schema — minimal info for embedding elsewhere
 */
export const UsageLimitReferenceSchema = UsageLimitBaseSchema.pick({
  id: true,
  metric: true,
  limit: true,
  period: true,
  createdAt: true,
});

/**
 * Detailed schema — includes nested relations
 */
export const UsageLimitDetailedSchema = UsageLimitBaseSchema.extend({
  app: z.lazy(() => AppReferenceSchema),
  endUser: z.lazy(() => EndUserReferenceSchema).optional(),
});

// Types
export type UsageLimitBase = z.infer<typeof UsageLimitBaseSchema>;
export type UsageLimitReference = z.infer<typeof UsageLimitReferenceSchema>;
export type UsageLimitDetailed = z.infer<typeof UsageLimitDetailedSchema>;
